    c.emit(arm32::bx(C::Ne,R::LR))?;
    // ARM VMA 0xb7bb0
    c.emit(arm32::data_immediate(C::Al,Op::Mov,R::R2,R::R0,7)?)?;
    // ARM VMA 0xb7bb4
    c.emit(arm32::transfer_word(C::Al,false,R::R2,R::R0,236)?)?;
    // ARM VMA 0xb7bb8
    c.emit(arm32::transfer_word(C::Al,true,R::R0,R::R1,28)?)?;
    // ARM VMA 0xb7bbc
    c.b(C::Al,0x292c,false)?;
