    // ARM VMA 0xb7c20
    c.emit(arm32::data_immediate(C::Al,Op::Add,R::new(7)?,R::new(7)?,1)?)?;
    // ARM VMA 0xb7c24
    c.emit(arm32::data_register(C::Lt,Op::Eor,R::new(3)?,R::new(5)?,R::new(4)?,Shift::Lsl,1,false)?)?;
    // ARM VMA 0xb7c28
