    // ARM VMA 0xb7c68
    c.emit(arm32::data_register(C::Al,Op::Add,R::new(7)?,R::new(3)?,R::R2,Shift::Lsl,0,false)?)?;
    // ARM VMA 0xb7c6c
    c.emit(arm32::transfer_byte_register(C::Al,true,R::new(3)?,R::new(8)?,R::new(3)?,Shift::Lsl,0)?)?;
    // ARM VMA 0xb7c70
